svg.script:
const dropZone = document.getElementById('drop-zone');
const fileInput = document.getElementById('fileInput');
const openBtn = document.getElementById('openBtn');

let htmlContent = '';

function readFile(file) {

  const reader = new FileReader();

  reader.onload = function(e) {

    htmlContent = e.target.result;

    console.log('File read successfully');

  };

  reader.onerror = function() {

    htmlContent = '';

    alert('Could not read the HTML file.');

  };

  reader.readAsText(file);

}

dropZone.addEventListener('dragover', (e) => {

  e.preventDefault();

  dropZone.style.borderColor = '#0056b3';

});

dropZone.addEventListener('dragleave', () => {

  dropZone.style.borderColor = '#007BFF';

});

dropZone.addEventListener('drop', (e) => {

  e.preventDefault();

  dropZone.style.borderColor = '#007BFF';

  const file = e.dataTransfer.files[0];

  if (
    file &&
    (
      file.type === 'text/html' ||
      file.name.toLowerCase().endsWith('.html')
    )
  ) {

    readFile(file);

  } else {

    alert('Please drop an HTML file.');

  }

});

fileInput.addEventListener('change', (e) => {

  const file = e.target.files[0];

  if (
    file &&
    (
      file.type === 'text/html' ||
      file.name.toLowerCase().endsWith('.html')
    )
  ) {

    readFile(file);

  }

});

openBtn.addEventListener('click', () => {

  if (!htmlContent) {

    alert('Please upload an HTML file first.');

    return;

  }

  /*
   * Create a temporary HTML document.
   * The browser loads this as its own document,
   * rather than trying to render the HTML inside the SVG.
   */
  const blob = new Blob(
    [htmlContent],
    { type: 'text/html' }
  );

  const url = URL.createObjectURL(blob);

  const newTab = window.open(url, '_blank');

  if (!newTab) {

    URL.revokeObjectURL(url);

    alert('Please allow popups for this site.');

    return;

  }

  /*
   * Keep the Blob URL alive long enough for the
   * new document to load.
   */
  setTimeout(() => {

    URL.revokeObjectURL(url);

  }, 60000);

});
